import numpy as np
def equation(t, P, params):
    p=params
    r=p[1]+p[2]*t
    K=p[3]+p[4]*t
    return p[0]/P + r*P*(1-P/K) + p[5]*t*P**2*np.log(P) + p[6]*P*np.log(P)
